                return

            grid[row][col] = '0'  # Mark as visited (sink the island)

            # Explore adjacent cells
            dfs(row + 1, col)
            dfs(row - 1, col)
            dfs(row, col + 1)
            dfs(row, col - 1)

        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == '1':
                    num_islands += 1
                    dfs(i, j)  # Explore the island using DFS

        return num_islands

