                formed += 1

            while left <= right and formed == required:
                char = s[left]

                if right - left + 1 < min_len:
                    min_len = right - left + 1
                    start = left

                window_freq[char] -= 1
                if char in t_freq and window_freq[char] < t_freq[char]:
                    formed -= 1

                left += 1
            right += 1

        if min_len == float('inf'):
            return ""
        else:
            return s[start:start + min_len]

