            left_tail = preorder_flatten(node.left)
            right_tail = preorder_flatten(node.right)

            if node.left:
                tail = node.left
                while tail.right:
                    tail = tail.right
                tail.right = node.right
                node.right = node.left
                node.left = None

            return right_tail or left_tail or node

        preorder_flatten(root)

