        for u, v in roads:
            adj[u - 1].append(v - 1)
            adj[v - 1].append(u - 1)

        visited = [False] * n
        stack = [(start - 1, -1)]  # (city, previous_city)
        total_score = 0

        while stack:
            city, prev_city = stack.pop()

            if not visited[city]:
                visited[city] = True
                total_score += scores[city]

            for neighbor in adj[city]:
                if neighbor != prev_city:
                    stack.append((neighbor, city))

