        inversions = 0
        for i in range(n):
            pos_count = 0
            neg_count = 0
            for j in range(i + 1, n):
                if seq[i] > seq[j]:
                    pos_count += 1
                if -seq[i] > seq[j]:
                    neg_count += 1
            for j in range(i + 1, n):
                if seq[i] > -seq[j]:
                    pos_count += 1
                if -seq[i] > -seq[j]:
