class Solution:
    def max_possible_f(self, n: int, edges: List[List[int]], usage: List[int]) -> int:
        """
        Finds the maximum possible value of f(G) after removing some edges.

        Args:
            n: The number of nodes in the graph.
            edges: A list of edges in the graph. Each edge is a list of two integers, representing the two nodes connected by the edge.
            usage: A list of integers, where usage[i] is the number of times node i is used by all paths.

        Returns:
            The maximum possible value of f(G) after removing some edges.
        """

        parent = list(range(n))
        rank = [0] * n

        def find(i):
            if parent[i] == i:
                return i
            parent[i] = find(parent[i])
            return parent[i]

        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                if rank[root_i] < rank[root_j]:
                    parent[root_i] = root_j
                elif rank[root_i] > rank[root_j]:
                    parent[root_j] = root_i
                else:
                    parent[root_j] = root_i
                    rank[root_i] += 1
                return True
            return False

        initial_components = 0
        for i in range(n):
            if parent[i] == i:
                initial_components += 1

        # Calculate the initial sum of usage values for each connected component.
        component_usage = {}
        for i in range(n):
            root = find(i)
            if root not in component_usage:
                component_usage[root] = 0
            component_usage[root] += usage[i]

        # Calculate the initial f(G) value.
        initial_f = sum(x * x for x in component_usage.values())

        # Iterate through the edges and try removing them.
        max_f = initial_f
        for i in range(1 << len(edges)):
            # Create a new graph without the edges that are removed.
            current_parent = list(range(n))
            current_rank = [0] * n
            num_removed_edges = 0

            def current_find(i):
                if current_parent[i] == i:
                    return i
                current_parent[i] = current_find(current_parent[i])
                return current_parent[i]

            def current_union(i, j):
                root_i = current_find(i)
                root_j = current_find(j)
                if root_i != root_j:
                    if current_rank[root_i] < current_rank[root_j]:
                        current_parent[root_i] = root_j
                    elif current_rank[root_i] > current_rank[root_j]:
                        current_parent[root_j] = root_i
                    else:
                        current_parent[root_j] = root_i
                        current_rank[root_i] += 1
                    return True
                return False

            for j in range(len(edges)):
                if (i >> j) & 1 == 0:
                    current_union(edges[j][0], edges[j][1])
                else:
                    num_removed_edges+=1

            # Calculate the sum of usage values for each connected component in the new graph.
            current_component_usage = {}
            for k in range(n):
                root = current_find(k)
                if root not in current_component_usage:
                    current_component_usage[root] = 0
                current_component_usage[root] += usage[k]

            # Calculate the f(G) value for the new graph.
            current_f = sum(x * x for x in current_component_usage.values())

            # Update the maximum f(G) value.
            max_f = max(max_f, current_f)

        return max_f
